// Blog posts and footer "Best School in ..." pages carried over from the old
// WordPress site (garimaschool.com). Generated by scripts/import-old-site.py —
// re-run that script instead of editing the JSON by hand.
//
// Both are served at their OLD URLs (/<slug>) by src/app/[slug]/page.tsx, so the
// Google rankings they've built up carry over without a redirect.

import blogsData from '@/data/blogs.json';
import landingData from '@/data/seoLandingPages.json';

export type LegacyPage = {
  slug: string;
  title: string;
  seoTitle: string;
  metaDescription: string;
  image: string | null;
  html: string;
};

export type BlogPost = LegacyPage & {
  date: string;
  modified: string;
  excerpt: string;
};

// Newest first (the import script already sorts them).
export const BLOG_POSTS = blogsData as BlogPost[];
export const SEO_LANDING_PAGES = landingData as LegacyPage[];

export function findBlogPost(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug);
}

export function findLandingPage(slug: string): LegacyPage | undefined {
  return SEO_LANDING_PAGES.find((p) => p.slug === slug);
}

export function formatBlogDate(value: string): string {
  const [y, m, d] = value.split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });
}
